import{_ as a,o as t,c as o,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Creator Task Creation Policy — Spec","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/04-task-chat-vault/creator-task-creation-policy/spec.md","filePath":"feature/modules/04-task-chat-vault/creator-task-creation-policy/spec.md"}'),s={name:"feature/modules/04-task-chat-vault/creator-task-creation-policy/spec.md"};function c(n,e,l,d,i,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="creator-task-creation-policy-—-spec" tabindex="-1">Creator Task Creation Policy — Spec <a class="header-anchor" href="#creator-task-creation-policy-—-spec" aria-label="Permalink to &quot;Creator Task Creation Policy — Spec&quot;">​</a></h1><p>&gt; Module: 04-task-chat-vault · Related FR: 3.6.x Create Task (standalone) · Roles: Owner, Manager, Creator</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>Creators could create any Task themselves and it started immediately (self-assigned, <code>IN_PROGRESS</code>). In an agency workspace the Manager plans and assigns the work, so the Owner needs to be able to limit this.</p><h2 id="rule" tabindex="-1">Rule <a class="header-anchor" href="#rule" aria-label="Permalink to &quot;Rule&quot;">​</a></h2><p>A workspace setting <code>creatorTaskCreation</code> controls Tasks <strong>of every type</strong> that a <strong>Creator</strong> creates:</p><table tabindex="0"><thead><tr><th>Value</th><th>Behaviour</th></tr></thead><tbody><tr><td><code>DISABLED</code></td><td>Creator cannot create Tasks (MSG: &quot;This Workspace does not allow Creators to create Tasks&quot;). The create buttons are hidden.</td></tr><tr><td><code>FREE</code> (default, same as before)</td><td>Creator creates the Task and it starts right away.</td></tr><tr><td><code>APPROVAL</code></td><td>Creator sends a proposal. The Task stays <code>TODO</code> with <code>creationApproval.state = PENDING</code>, workflow locked (<code>TASK_CREATION_PENDING</code>), no draft post yet. Owner/Manager approve or reject.</td></tr></tbody></table><ul><li>Owner and Manager are never gated.</li><li>Only Owner/Manager change the setting (Workspace detail page).</li><li>Approve: <code>creationApproval = APPROVED</code>. Standalone Tasks (<code>sourceType = MANUAL</code>) move to <code>IN_PROGRESS</code> and get their draft post (POST / SHORT_VIDEO). The Creator gets a notification.</li><li>Reject: <code>creationApproval = REJECTED</code>, Task <code>CANCELLED</code> (reason <code>NO_LONGER_SUITABLE</code>, optional note). The Creator gets a notification with the note.</li><li>When a proposal is sent, every active Owner/Manager gets an inbox notification.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><ul><li>Mobile app UI (backend already enforces the policy for mobile requests).</li><li>Campaign out-of-scope Tasks: already Owner/Manager only.</li></ul>',10)])])}const k=a(s,[["render",c]]);export{u as __pageData,k as default};
